content.content:
1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8"/>
5	<meta name="viewport" content="width=device-width, initial-scale=1"/>
6	<title>Creator Engine — the dark software factory</title>
7	<style>
8	  :root{
9	    --violet:#A06BFF; --violet-bright:#B98CFF; --violet-deep:#6E3CD6; --violet-soft:rgba(160,107,255,.16);
10	    --ink:#0C0B0A; --panel:#16140F; --panel-2:#191712; --line:rgba(255,255,255,.10);
11	    --paper:#FAF8F1; --muted:#9A968C; --moss:#7FB069; --oxide:#E08B4C;
12	    --mono:'SFMono-Regular',ui-monospace,Menlo,Consolas,monospace;
13	    --sans:'Inter',system-ui,-apple-system,Segoe UI,Roboto,sans-serif;
14	  }
15	  *{box-sizing:border-box;margin:0;padding:0}
16	  html{scroll-behavior:smooth}
17	  body{background:var(--ink);color:var(--paper);font-family:var(--sans);line-height:1.5;-webkit-font-smoothing:antialiased;overflow-x:hidden}
18	  .wrap{max-width:1180px;margin:0 auto;padding:0 28px}
19	  .eyebrow{font-family:var(--mono);font-size:11px;letter-spacing:.22em;text-transform:uppercase;color:var(--violet)}
20	  h1,h2{font-weight:700;letter-spacing:-.02em;line-height:1.05}
21	  .nav{display:flex;justify-content:space-between;align-items:center;padding:22px 28px;max-width:1180px;margin:0 auto}
22	  .logo{display:flex;align-items:center;gap:11px;font-family:var(--mono);font-size:13px;letter-spacing:.16em;text-transform:uppercase}
23	  .logo .arm{width:24px;height:24px}
24	  .nav a{color:var(--muted);text-decoration:none;font-size:13px;margin-left:26px;transition:color .15s}
25	  .nav a:hover{color:var(--paper)}
26	
27	  /* ===== SECTION 1 — THE CONVEYOR (placeholder — high-fidelity assembly line in design) ===== */
28	  .hero{padding:62px 0 30px;text-align:center}
29	  .hero h1{font-size:clamp(34px,6vw,62px)}
30	  .hero h1 em{font-style:normal;color:var(--violet)}
31	  .hero p.sub{color:var(--muted);font-size:clamp(15px,2vw,19px);max-width:620px;margin:20px auto 0}
32	  .factory{margin:46px auto 0;max-width:1100px;background:linear-gradient(180deg,var(--panel-2),var(--panel));border:1px solid var(--line);border-radius:18px;padding:34px 26px 26px;position:relative;overflow:hidden}
33	  .factory::before{content:"";position:absolute;inset:0;background:radial-gradient(120% 80% at 50% -10%,var(--violet-soft),transparent 60%);pointer-events:none}
34	  .belt-track{position:relative;height:240px}
35	  .belt{position:absolute;left:0;right:0;bottom:48px;height:26px;background:repeating-linear-gradient(90deg,#2a2620 0 22px,#211d18 22px 44px);border-top:2px solid var(--violet-deep);border-bottom:2px solid #000;border-radius:3px}
36	  .belt::after{content:"";position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 40px,rgba(160,107,255,.10) 40px 44px);animation:beltmove 1.1s linear infinite}
37	  @keyframes beltmove{to{background-position:44px 0}}
38	  .stations{position:absolute;left:0;right:0;bottom:80px;display:flex;justify-content:space-between;padding:0 24px}
39	  .station{flex:1;text-align:center}
40	  .station .stage{font-family:var(--mono);font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
41	  .station.active .stage{color:var(--violet-bright)}
42	  .station .post{width:2px;height:46px;background:var(--line);margin:6px auto 0}
43	  .station.active .post{background:var(--violet)}
44	  .anim-note{position:absolute;top:12px;right:16px;font-family:var(--mono);font-size:10px;color:var(--oxide);letter-spacing:.06em;border:1px dashed rgba(224,139,76,.4);border-radius:6px;padding:4px 8px}
45	  .caption{margin-top:18px;font-family:var(--mono);font-size:12px;color:var(--muted);letter-spacing:.04em}
46	  .caption b{color:var(--paper);font-weight:600}
47	
48	  /* ===== SECTION 2 — INSTALL ===== */
49	  .install{padding:90px 0 70px;text-align:center}
50	  .install h2{font-size:clamp(26px,4vw,40px)}
51	  .install .standout{font-size:clamp(20px,3vw,30px);font-weight:700;color:var(--violet-bright);margin:18px auto 0;letter-spacing:-.01em}
52	  .install .lede{color:var(--muted);margin:14px auto 0;max-width:600px}
53	  .link-playbook{font:inherit;color:var(--violet);background:transparent;border:none;border-bottom:1.5px dashed var(--violet);cursor:pointer;padding:0 1px;transition:color .15s,border-color .15s}
54	  .link-playbook:hover{color:var(--violet-bright);border-color:var(--violet-bright)}
55	  .link-playbook.copied{color:var(--moss);border-bottom-style:solid;border-color:var(--moss)}
56	  .install-blocks{max-width:780px;margin:34px auto 0;display:flex;flex-direction:column;gap:16px;text-align:left}
57	  .iblock-label{font-family:var(--mono);font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin-bottom:8px}
58	  .cmd{display:flex;align-items:center;gap:14px;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:16px 18px;font-family:var(--mono);font-size:13.5px}
59	  .cmd .dollar{color:var(--violet)}
60	  .cmd code{flex:1;color:var(--paper);overflow-x:auto;white-space:nowrap}
61	  .iblock.agent .cmd code{white-space:normal}
62	  .cmd .copy{font-family:var(--mono);font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--violet);border:1px solid var(--line);border-radius:8px;padding:7px 13px;background:transparent;cursor:pointer;white-space:nowrap}
63	  .cmd .copy:hover{border-color:var(--violet)}
64	
65	  /* ===== SECTION 3 — COCKPIT ===== */
66	  .cockpit{padding:30px 0 100px}
67	  .cockpit-head{text-align:center;margin-bottom:34px}
68	  .cockpit-head h2{font-size:clamp(26px,4vw,40px)}
69	  .cockpit-head p{color:var(--muted);margin-top:12px}
70	  .screen{max-width:1000px;margin:0 auto;background:var(--panel);border:1px solid var(--line);border-radius:16px;overflow:hidden;box-shadow:0 20px 60px rgba(0,0,0,.5)}
71	  .screen-bar{display:flex;align-items:center;gap:8px;padding:12px 16px;border-bottom:1px solid var(--line);background:var(--panel-2)}
72	  .dot{width:11px;height:11px;border-radius:50%}
73	  .screen-bar .t{margin-left:12px;font-family:var(--mono);font-size:12px;color:var(--muted)}
74	  .board{display:grid;grid-template-columns:repeat(5,1fr)}
75	  .col{padding:16px 14px;border-right:1px solid var(--line)}
76	  .col:last-child{border-right:0}
77	  .col h4{font-family:var(--mono);font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin-bottom:12px}
