=== CSS rule line ranges ===
237:  .band{padding:72px 0}
238:  .band.alt{background:var(--paper-2);border-top:1px solid var(--line-soft);border-bottom:1px solid var(--line-soft)}
239:  .sec-head{max-width:60ch;margin-bottom:34px}
240:  .sec-eyebrow{display:block;margin-bottom:12px;font-family:var(--mono);font-size:11.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--violet)}
241:  .sec-head h2{margin:0 0 12px;font-family:var(--serif);font-weight:600;font-size:clamp(26px,3.4vw,36px);line-height:1.15}
242:  .sec-head p{margin:0;font-size:16.5px;color:var(--ink-soft)}
253:  .pair{display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:start}
254:  @media (max-width:860px){.pair{grid-template-columns:1fr}}
255:  .pcard{border:1px solid var(--line);border-radius:12px;background:var(--paper-2);overflow:hidden}
256:  .pcard.scope{border-color:rgba(160,107,255,.26)} .pcard.report{border-color:rgba(155,227,79,.24)}
257:  .pcard .h{display:flex;justify-content:space-between;gap:10px;padding:10px 16px;border-bottom:1px solid var(--line-soft);font-family:var(--mono);font-size:11.5px;color:var(--ink-faint)}
258:  .pcard .h .ce{color:var(--violet)} .pcard.report .h .ce{color:var(--moss)} .pcard .h .ok{color:var(--moss)}
259:  .pcard .b{padding:18px 18px 8px}
260:  .pcard .t{font-family:var(--serif);font-size:18px;font-weight:600;margin:0 0 12px}
264:  .pcard.report .fld b{color:var(--moss)}
267:  .stages{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}
268:  @media (max-width:920px){.stages{grid-template-columns:repeat(3,1fr)}}
269:  @media (max-width:600px){.stages{grid-template-columns:1fr 1fr}}
270:  .stage{border:1px solid var(--line);border-radius:12px;background:var(--paper-2);padding:16px}
271:  .stage .n{font-family:var(--mono);font-size:11px;color:var(--violet)}
272:  .stage h3{margin:8px 0 5px;font-family:var(--serif);font-weight:600;font-size:16.5px}
273:  .stage p{margin:0;font-size:12.5px;color:var(--ink-soft)}
276:  .compl{display:grid;grid-template-columns:1fr auto 1fr;gap:18px;align-items:stretch}
277:  @media (max-width:780px){.compl{grid-template-columns:1fr}.compl .plus{transform:rotate(90deg);justify-self:center}}
278:  .plate{border:1px solid var(--line);border-radius:12px;background:var(--paper-2);padding:22px}
279:  .plate .k{font-family:var(--mono);font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--ink-faint)}
280:  .plate.ce{border-color:rgba(160,107,255,.26)} .plate.ce .k{color:var(--violet)} .plate.os .k{color:var(--moss)}
281:  .plate h3{margin:8px 0 6px;font-family:var(--serif);font-weight:600;font-size:19px}
282:  .plate p{margin:0;font-size:14px;color:var(--ink-soft)}
283:  .plus{align-self:center;font-size:24px;color:var(--ink-faint)}
284:  .honest{margin-top:18px;padding-left:14px;border-left:2px solid var(--amber);font-family:var(--mono);font-size:12.5px;color:var(--ink-faint);max-width:72ch}
286:  /* fear map — live-site .safe/.srow styling (v7.3) */
287:  .safe{display:grid;grid-template-columns:1fr 1fr;gap:16px}
288:  @media (max-width:820px){.safe{grid-template-columns:1fr}}
289:  .srow{display:grid;grid-template-columns:1fr 1fr;border:1px solid var(--line-soft);border-radius:14px;overflow:hidden;background:var(--paper-2)}
290:  .srow .fear{padding:15px 17px;border-right:1px solid var(--line-soft)}
291:  .srow .mech{padding:15px 17px;background:rgba(160,107,255,0.04)}
