@media (max-width:820px){.safe{grid-template-columns:1fr}}
.srow{display:grid;grid-template-columns:1fr 1fr;border:1px solid var(--line);border-radius:14px;overflow:hidden;background:var(--panel-2)}
.srow .fear{padding:15px 17px;border-right:1px solid var(--line)}
.srow .mech{padding:15px 17px;background:rgba(160,107,255,.05)}
.srow .lab{font-family:var(--mono);font-size:10.5px;letter-spacing:.1em;text-transform:uppercase;margin-bottom:6px}
.srow .fear .lab{color:var(--oxide)} .srow .mech .lab{color:var(--violet)}
.srow .fear p{margin:0;font-size:14px;color:var(--paper)} .srow .mech p{margin:0;font-size:13px;color:var(--muted)} .srow .mech code{color:var(--moss);font-size:12.5px}
@media (max-width:460px){.srow{grid-template-columns:1fr}.srow .fear{border-right:0;border-bottom:1px solid var(--line)}}
.caps{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.cap{background:var(--panel-2);border:1px solid var(--line);border-radius:14px;padding:22px;transition:border-color .18s,box-shadow .18s}
.cap:hover{border-color:var(--violet-deep);box-shadow:0 0 30px -16px var(--violet-soft)}
.cap .icon{width:36px;height:36px;border-radius:9px;display:grid;place-items:center;background:var(--violet-soft);border:1px solid var(--line);margin-bottom:14px}
.cap .icon svg{width:18px;height:18px;stroke:var(--violet)}
.cap h3{font-size:16px;margin:0 0 7px;font-weight:700;color:var(--paper)} .cap p{margin:0;font-size:13.5px;color:var(--muted);line-height:1.55} .cap code{color:var(--moss);font-size:12.5px}
.cap .faint{color:var(--muted);opacity:.8}
@media (max-width:880px){.caps{grid-template-columns:repeat(2,1fr)}}
@media (max-width:560px){.caps{grid-template-columns:1fr}}
.cta{position:relative;overflow:hidden;padding:84px 0;text-align:center;border-top:1px solid var(--line)}
.cta::before{content:"";position:absolute;inset:0;background:radial-gradient(620px 320px at 34% 0%,rgba(127,176,105,.10),transparent 70%),radial-gradient(560px 300px at 72% 14%,var(--violet-soft),transparent 70%);pointer-events:none}
.cta .inner{position:relative;z-index:1;max-width:64ch;margin:0 auto}
.cta .eyebrow-lime{display:inline-flex;justify-content:center;font-family:var(--mono);font-size:12px;letter-spacing:.16em;text-transform:uppercase;margin:0 0 14px;color:var(--moss)}
.cta h2{margin:0 0 16px;font-weight:700;letter-spacing:-.02em;font-size:clamp(30px,4.4vw,46px)} .cta h2 .make{color:var(--moss)}
.cta p{margin:0 0 30px;color:var(--muted);font-size:17px;line-height:1.6}
.cta .row{display:flex;justify-content:center;gap:14px;flex-wrap:wrap}
.btn svg{width:16px;height:16px}
.btn{display:inline-flex;align-items:center;gap:9px;padding:12px 22px;border-radius:999px;font-size:15px;font-weight:600;text-decoration:none;border:1px solid transparent;cursor:pointer}
.btn.dark{background:var(--moss);color:#0a1a05;box-shadow:0 0 0 1px rgba(127,176,105,.5)}
.btn.dark:hover{background:#93c47e}
.btn.ghost{background:var(--violet);color:#08090F;border-color:var(--violet-deep)}
.btn.ghost:hover{background:var(--violet-bright);border-color:var(--violet)}

